<?php
declare(strict_types=1);
/** Unchanged post-media helpers; disposable SQL and recorded external transports. */
$conn=(string)getenv('LIBRARY_FIXTURE_DB');if(!str_contains($conn,'/tmp/'))throw new RuntimeException('disposable local PostgreSQL required');
$pg=new PDO('pgsql:'.$conn,'postgres',null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
function ap_db():PDO{return $GLOBALS['post_media_db'];}
function ap_php_cli_binary():string{return '/usr/bin/php';}
function lp_post_media_temp_dir():string{return $GLOBALS['post_media_root'];}
if(extension_loaded('redis'))throw new RuntimeException('recording fixture requires unloaded Redis extension');
class Redis {public function set(string $key,string $value,array $options):bool{$GLOBALS['post_media_locks'][]=compact('key','value','options');return (bool)$GLOBALS['post_media_lock_allowed'];}}
function ap_redis_client(string $purpose='cache'):?Redis{$GLOBALS['post_media_redis_purposes'][]=$purpose;return $GLOBALS['post_media_redis_available']?new Redis():null;}
function ap_redis_metric_inc(string $name,int $amount=1):void{$GLOBALS['post_media_metrics'][]=compact('name','amount');}
$root='/tmp/vaak-post-media-php-helper-'.getmypid();mkdir($root);$GLOBALS['post_media_root']=$root;
file_put_contents($root.'/ap-media-warm-worker.php','<?php file_put_contents(getenv("LP_POST_MEDIA_ARGV_RECORD"),json_encode($argv)."\n",FILE_APPEND|LOCK_EX);');
putenv('LP_POST_MEDIA_ARGV_RECORD='.$root.'/argv.jsonl');$hashes=[];$declarations=[];
foreach(['ap-db.php'=>['ap_db_now','ap_profile_sanitize_https_url'],'ap-redis.php'=>['ap_redis_lock'],'ap-r2.php'=>['ap_remote_post_media_get','ap_remote_post_media_touch','ap_remote_post_media_resolve','ap_media_warm_enqueue_post','ap_media_warm_worker_nudge']] as $file=>$names){
 $source=(string)file_get_contents(dirname(__DIR__).'/'.$file);
 foreach($names as $name){if(!preg_match('/^function '.preg_quote($name,'/').'\(.*?^}/ms',$source,$match))throw new RuntimeException($name);
  $declarations[$name]=$match[0];$hashes[$name]=hash('sha256',$match[0]);$resolved='';
  foreach(token_get_all('<?php '.$match[0]) as $token){if(is_array($token)&&$token[0]===T_DIR)$resolved.=var_export($root,true);elseif(is_array($token)&&$token[0]===T_STRING&&$token[1]==='sys_get_temp_dir')$resolved.='lp_post_media_temp_dir';else $resolved.=is_array($token)?$token[1]:$token;}
  eval(substr($resolved,5));
 }
}
$dbSource=(string)file_get_contents(dirname(__DIR__).'/ap-db.php');$ddls=[];
foreach(['remote_post_media_cache','ap_media_warm_queue'] as $table){if(!preg_match('/CREATE TABLE IF NOT EXISTS '.$table.' \(\n\s*id INTEGER PRIMARY KEY AUTOINCREMENT,.*?\n\);/s',$dbSource,$match))throw new RuntimeException('actual DDL '.$table);$ddls[$table]=$match[0];}
$captures=[];$schemas=[];
foreach(['INTEGER','BIGINT'] as $width){$schema='post_media_helper_php_'.strtolower($width).'_'.getmypid();$pg->exec('CREATE SCHEMA '.$schema.';SET search_path='.$schema);$GLOBALS['post_media_db']=$pg;
 try{
  foreach($ddls as $ddl)$pg->exec(str_replace('INTEGER PRIMARY KEY AUTOINCREMENT',$width.' GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY',$ddl));
  foreach($pg->query('SELECT table_name,column_name,data_type FROM information_schema.columns WHERE table_schema=current_schema() ORDER BY table_name,ordinal_position')->fetchAll() as $column)$schemas[$width][$column['table_name']][]=['column_name'=>$column['column_name'],'data_type'=>$column['data_type']];
  foreach(['cold','duplicate_pending','duplicate_succeeded','duplicate_failed','redis_acquired','redis_contended','cached','cached_zero','cached_empty','invalid_http','invalid_private','trimmed','nudge_locked','sql_error'] as $case){
   $pg->exec('DELETE FROM remote_post_media_cache;DELETE FROM ap_media_warm_queue');@unlink($root.'/argv.jsonl');
   $GLOBALS['post_media_redis_available']=str_starts_with($case,'redis_');$GLOBALS['post_media_lock_allowed']=$case!=='redis_contended';foreach(['post_media_locks','post_media_metrics','post_media_redis_purposes'] as $global)$GLOBALS[$global]=[];
   $url='https://media.test/image.jpg';if($case==='invalid_http')$url='http://media.test/image.jpg';if($case==='invalid_private')$url='https://127.0.0.1/image.jpg';if($case==='trimmed')$url='  https://media.test/image.jpg  ';
   if(str_starts_with($case,'duplicate_')){$status=substr($case,10);$pg->prepare("INSERT INTO ap_media_warm_queue(job_type,target_key,media_kind,status,attempts,max_attempts,next_attempt_at,created_at,updated_at) VALUES('post_media',?,'image',?,3,5,'original','original','original')")->execute([$url,$status]);}
   if(str_starts_with($case,'cached')){$public=$case==='cached'?'https://media.test/cached.webp':($case==='cached_zero'?'0':'');$pg->prepare("INSERT INTO remote_post_media_cache(source_url,s3_key,public_url,content_type,fetched_at,last_used_at) VALUES(?,'cached',?,'image/webp','original','original')")->execute([$url,$public]);}
   $before=['ap_media_warm_queue'=>$pg->query('SELECT * FROM ap_media_warm_queue ORDER BY id')->fetchAll(),'remote_post_media_cache'=>$pg->query('SELECT * FROM remote_post_media_cache ORDER BY id')->fetchAll()];
   $lock=null;if($case==='nudge_locked'){$lock=fopen($root.'/vaak-media-warm-worker.lock','c+');if(!flock($lock,LOCK_EX|LOCK_NB))throw new RuntimeException('owned lock');}
   if($case==='sql_error')$pg->exec('ALTER TABLE ap_media_warm_queue RENAME TO unavailable_queue');
   $returned=ap_remote_post_media_resolve($url);
   if($case==='sql_error')$pg->exec('ALTER TABLE unavailable_queue RENAME TO ap_media_warm_queue');
   if(is_resource($lock)){flock($lock,LOCK_UN);fclose($lock);}
   $expectedSpawn=in_array($case,['cold','redis_acquired','cached_zero','cached_empty','trimmed'],true);if($expectedSpawn)for($attempt=0;$attempt<100&&!is_file($root.'/argv.jsonl');$attempt++)usleep(5000);
   $argvRows=[];foreach((is_file($root.'/argv.jsonl')?file($root.'/argv.jsonl',FILE_IGNORE_NEW_LINES):[])?:[] as $line)$argvRows[]=json_decode($line,true,512,JSON_THROW_ON_ERROR);
   if(count($argvRows)!==($expectedSpawn?1:0))throw new RuntimeException('actual nudge count '.$case);
   $after=['ap_media_warm_queue'=>$pg->query('SELECT * FROM ap_media_warm_queue ORDER BY id')->fetchAll(),'remote_post_media_cache'=>$pg->query('SELECT * FROM remote_post_media_cache ORDER BY id')->fetchAll()];
   $captures[]=['width'=>$width,'case'=>$case,'url'=>$url,'returned'=>$returned,'before'=>$before,'after'=>$after,'redis_available'=>$GLOBALS['post_media_redis_available'],'locks'=>$GLOBALS['post_media_locks'],'metrics'=>$GLOBALS['post_media_metrics'],'redis_purposes'=>$GLOBALS['post_media_redis_purposes'],'nudge_argv'=>$argvRows];
  }
 }finally{$pg->exec('DROP SCHEMA '.$schema.' CASCADE');}
}
$out=$argv[1]??'/tmp/vaak-profile-post-media-warm-reference.json';file_put_contents($out,json_encode(['captures'=>$captures,'current_schema_by_width'=>$schemas,'declaration_sha256'=>$hashes,'original_declarations'=>$declarations,'actual_ddl'=>$ddls,'transport_substitutions'=>['Redis SET/metric recorder, unchanged ap_redis_lock declaration','worker argv recorder in owned API and temp directory, unchanged nudge branch/lock/spawn','actual native PHP CLI binary /usr/bin/php'],'scope'=>'actual cold post-media resolve/enqueue/touch/nudge; no actor-media substitution; not whole selected-source or runtime admission proof'],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE));
foreach(glob($root.'/*')?:[] as $file)unlink($file);rmdir($root);echo count($captures).' actual post-media helper cases: '.$out."\n";
